I would have used a [type guard](https://www.typescriptlang.org/docs/handbook/advanced-types.html#type-guards-and-differentiating-types) here to avoid multiple type casting:

```ts
function isEscapedHits<THit>(
  x: THit[] | EscapedHits<THit>
): x is EscapedHits<THit> {
  return typeof (x as EscapedHits<THit>).__escaped === 'boolean';
}

export default function escapeHits<THit extends Hit>(
  hits: THit[] | EscapedHits<THit>
): EscapedHits<THit> {
  if (!isEscapedHits(hits)) {
    return Object.assign(
      hits.map(hit => {
        if (hit._highlightResult) {
          hit._highlightResult = recursiveEscape(hit._highlightResult);
        }

        if (hit._snippetResult) {
          hit._snippetResult = recursiveEscape(hit._snippetResult);
        }

        return hit;
      }),
      { __escaped: true }
    );
  }

  return hits;
}
```

